import { tags } from "typia";

import { IShoppingWishlistItem } from "./IShoppingWishlistItem";

/**
 * Represents a customer-owned wishlist, as defined in the shopping_wishlists
 * table. Contains metadata and the full list of SKU items currently in the
 * wishlist. This object is used as the primary response for fetching and
 * updating customer wishlists, including all related SKU/product references.
 * Deleted_at is used for soft-delete logic and auditing.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingWishlist = {
  /**
   * Unique identifier for this wishlist. Corresponds to the primary key in
   * the shopping_wishlists table.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Identifier of the customer who owns this wishlist. This is a foreign key
   * to shopping_customers.id, but is only used internally and not shown in UI
   * responses.
   */
  shopping_customer_id: string & tags.Format<"uuid">;

  /**
   * Timestamp when the wishlist was created. Sourced from
   * shopping_wishlists.created_at.
   */
  created_at: string & tags.Format<"date-time">;

  /**
   * Timestamp of the most recent update (item add/remove, rename, etc.), from
   * shopping_wishlists.updated_at.
   */
  updated_at: string & tags.Format<"date-time">;

  /**
   * Current array of items (SKUs) included in this wishlist. Each includes
   * SKU/product summary for UI display.
   */
  items: IShoppingWishlistItem[];
};
export namespace IShoppingWishlist {
  /**
   * DTO for wishlist item retrieval options (search/filter/query params).
   * Includes pagination, search, tag/category filters, stock-only filtering,
   * and sort order. Used as the request body or query parameter bag for
   * wishlist list endpoints. The request is always scoped to the
   * authenticated customer account. Defaults: page=1, limit=20,
   * sort_by=recent.
   */
  export type IRequest = {
    /** The page number for pagination (defaults to 1 if omitted). */
    page?: (number & tags.Type<"int32"> & tags.Minimum<1>) | undefined;

    /**
     * Maximum number of items per page for wishlist list results. Platform
     * default is 20 and maximum allowed is 100.
     */
    limit?:
      | (number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>)
      | undefined;

    /**
     * Optional keyword to search by product name, brand, or SKU within the
     * user's wishlist items.
     */
    search?: string | undefined;

    /**
     * List of tag codes to filter wishlist items by user-specified tags.
     * Only items with at least one matching tag will be included.
     */
    tag_codes?: string[] | undefined;

    /**
     * List of category codes to filter wishlist items for associated
     * product categories. Only wishlist items whose products belong to the
     * provided categories will be listed.
     */
    category_codes?: string[] | undefined;

    /**
     * Filter flag: if true, includes only wishlist items with currently
     * available/in-stock SKUs.
     */
    in_stock_only?: boolean | undefined;

    /**
     * Sort order for the wishlist items. Supported values: 'recent'
     * (default, most recently updated first), 'oldest', 'name',
     * 'price_asc', 'price_desc'.
     */
    sort_by?:
      | "recent"
      | "oldest"
      | "name"
      | "price_asc"
      | "price_desc"
      | undefined;
  };

  /**
   * Schema for updating the last modified date/time of a wishlist in the
   * shopping mall platform. Used exclusively in authenticated mutation
   * operations to ensure audit-compliant update timestamping, concurrency
   * protection, and transactional integrity. Ownership and context are always
   * inferred via authentication; this operation never accepts actor/ownership
   * fields in the request. This DTO should not be used for wishlist creation
   * or ownership transfer flows.
   */
  export type IUpdate = {
    /**
     * Timestamp indicating when the wishlist was last updated, in ISO 8601
     * UTC format (e.g., '2025-10-31T14:37:52.391Z'). Used by the platform
     * for concurrency, mutation audit, and historical trace in wishlist
     * update operations. Business logic mandates UTC for all audit and
     * transactional timestamps.
     */
    updated_at: string & tags.Format<"date-time">;
  };
}
